-- ===== 20261023140000_shelf_decor.sql =====
-- Shelf decoration (plants & co.) placed by the reader on their boards (additive).
-- Stored on the profile: [{"i": item, "r": board, "s": slot}], max 16 pieces.
create or replace function private.valid_shelf_decor(d jsonb)
returns boolean
language sql
immutable
set search_path = ''
as $$
  select jsonb_typeof(d) = 'array'
     and jsonb_array_length(d) <= 16
     and not exists (
       select 1 from jsonb_array_elements(d) e
       where jsonb_typeof(e) <> 'object'
          or (e ->> 'i') is null
          or (e ->> 'i') not in ('plant', 'cactus', 'flowers', 'candle', 'mug', 'cat',
                                 'teddy', 'trophy', 'picture', 'hourglass', 'globe', 'camera')
          or jsonb_typeof(e -> 'r') <> 'number' or (e ->> 'r')::int not between 0 and 49
          or jsonb_typeof(e -> 's') <> 'number' or (e ->> 's')::int not between 0 and 5
     );
$$;

alter table public.profiles
  add column if not exists shelf_decor jsonb not null default '[]'::jsonb;

alter table public.profiles drop constraint if exists profiles_shelf_decor_valid;
alter table public.profiles
  add constraint profiles_shelf_decor_valid check (private.valid_shelf_decor(shelf_decor));

-- ===== 20261023160000_shelf_order.sql =====
-- Reader-defined order of books on the shelf (additive; existing rows stay null = by age).
alter table public.user_books add column if not exists shelf_position int check (shelf_position > 0);

-- Saves the whole order at once: position = place in p_ids. Runs as the caller,
-- so RLS limits it to the caller's own rows.
create or replace function public.reorder_shelf(p_ids uuid[])
returns void
language sql
security invoker
set search_path = ''
as $$
  update public.user_books
     set shelf_position = array_position(p_ids, id)
   where user_id = (select auth.uid())
     and id = any(p_ids);
$$;
revoke all on function public.reorder_shelf(uuid[]) from public, anon;
grant execute on function public.reorder_shelf(uuid[]) to authenticated;

-- ===== 20261023180000_private_accounts.sql =====
-- Private accounts with follow requests (issue #12).
-- Private: others see only the profile card; shelf, wishlist and posts after an accepted request.
-- Reading-circle posts stay visible to circle members. Existing accounts stay public.

alter table public.profiles
  add column if not exists is_private boolean not null default false;

-- True when the caller may see the owner's shelf and posts.
create or replace function private.can_see_content(owner uuid)
returns boolean
language sql stable security definer set search_path = '' as $$
  select owner = (select auth.uid())
      or not coalesce((select p.is_private from public.profiles p where p.id = owner), false)
      or exists (
        select 1 from public.follows f
        where f.follower_id = (select auth.uid()) and f.following_id = owner
      );
$$;
revoke all on function private.can_see_content(uuid) from public, anon;
grant execute on function private.can_see_content(uuid) to authenticated;

drop policy if exists "User books visible to signed-in users" on public.user_books;
drop policy if exists "User books visible by privacy" on public.user_books;
create policy "User books visible by privacy" on public.user_books
  for select to authenticated using (private.can_see_content(user_id));

drop policy if exists "Posts visible by visibility rules" on public.posts;
create policy "Posts visible by visibility rules" on public.posts
  for select to authenticated using (
    (case when group_id is null then private.can_see_content(author_id)
          else private.can_view_group(group_id) end)
    and not private.is_blocked_with(author_id)
    and (hidden_at is null or author_id = (select auth.uid()))
  );

-- Comments and likes follow their post.
create or replace function private.can_view_post(pid uuid)
returns boolean
language sql stable security definer set search_path to 'public' as $$
  select exists (
    select 1 from public.posts p
    where p.id = pid
      and (case when p.group_id is null then private.can_see_content(p.author_id)
                else private.can_view_group(p.group_id) end)
      and not private.is_blocked_with(p.author_id)
      and (p.hidden_at is null or p.author_id = auth.uid())
  );
$$;

-- Direct follows only for public accounts; private ones go through follow_user().
drop policy if exists "Users follow unblocked users" on public.follows;
create policy "Users follow unblocked users" on public.follows
  for insert to authenticated with check (
    follower_id = (select auth.uid())
    and not private.is_blocked_with(following_id)
    and not coalesce((select p.is_private from public.profiles p where p.id = following_id), false)
  );

create table if not exists public.follow_requests (
  requester_id uuid not null references public.profiles(id) on delete cascade,
  target_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (requester_id, target_id),
  check (requester_id <> target_id)
);
create index if not exists follow_requests_target_id_idx on public.follow_requests (target_id);

alter table public.follow_requests enable row level security;
revoke all on public.follow_requests from anon, authenticated;
grant select, delete on public.follow_requests to authenticated;

drop policy if exists "Users see own follow requests" on public.follow_requests;
create policy "Users see own follow requests" on public.follow_requests
  for select to authenticated
  using (requester_id = (select auth.uid()) or target_id = (select auth.uid()));

-- Requester cancels, target declines.
drop policy if exists "Users withdraw or decline follow requests" on public.follow_requests;
create policy "Users withdraw or decline follow requests" on public.follow_requests
  for delete to authenticated
  using (requester_id = (select auth.uid()) or target_id = (select auth.uid()));

-- Follows a public account or asks a private one. Returns 'following' or 'requested'.
create or replace function public.follow_user(p_target uuid)
returns text
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  is_priv boolean;
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_target = me then
    raise exception 'cannot follow yourself' using errcode = '22023';
  end if;
  select p.is_private into is_priv from public.profiles p where p.id = p_target;
  if not found then
    raise exception 'profile not found' using errcode = 'P0002';
  end if;
  if private.is_blocked_with(p_target) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if exists (select 1 from public.follows where follower_id = me and following_id = p_target) then
    return 'following';
  end if;
  if is_priv then
    insert into public.follow_requests (requester_id, target_id)
      values (me, p_target) on conflict do nothing;
    return 'requested';
  end if;
  insert into public.follows (follower_id, following_id)
    values (me, p_target) on conflict do nothing;
  return 'following';
end;
$$;
revoke all on function public.follow_user(uuid) from public, anon;
grant execute on function public.follow_user(uuid) to authenticated;

create or replace function public.respond_follow_request(p_requester uuid, p_accept boolean)
returns void
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
begin
  delete from public.follow_requests
   where requester_id = p_requester and target_id = me;
  if not found then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if p_accept then
    insert into public.follows (follower_id, following_id)
      values (p_requester, me) on conflict do nothing;
  end if;
end;
$$;
revoke all on function public.respond_follow_request(uuid, boolean) from public, anon;
grant execute on function public.respond_follow_request(uuid, boolean) to authenticated;

-- Going public accepts every open request.
create or replace function private.accept_requests_on_public()
returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.follows (follower_id, following_id)
    select r.requester_id, r.target_id from public.follow_requests r
     where r.target_id = new.id
    on conflict do nothing;
  delete from public.follow_requests where target_id = new.id;
  return new;
end;
$$;
revoke all on function private.accept_requests_on_public() from public, anon, authenticated;

drop trigger if exists profiles_accept_requests_on_public on public.profiles;
create trigger profiles_accept_requests_on_public
  after update of is_private on public.profiles
  for each row when (old.is_private and not new.is_private)
  execute function private.accept_requests_on_public();

-- A block also drops pending requests in both directions.
create or replace function private.remove_follow_requests_on_block()
returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  delete from public.follow_requests
   where (requester_id = new.blocker_id and target_id = new.blocked_id)
      or (requester_id = new.blocked_id and target_id = new.blocker_id);
  return new;
end;
$$;
revoke all on function private.remove_follow_requests_on_block() from public, anon, authenticated;

drop trigger if exists on_block_remove_follow_requests on public.blocks;
create trigger on_block_remove_follow_requests
  after insert or update on public.blocks
  for each row execute function private.remove_follow_requests_on_block();

-- ===== 20261023200000_direct_messages.sql =====
-- Direct messages between mutual followers (issue #13).
-- 1:1 only: a conversation is the pair (user_a < user_b). Blocking or unfollowing ends it:
-- no new messages, and a block also hides the history.

-- Both follow each other and neither blocked the other.
create or replace function private.can_message(other uuid)
returns boolean
language sql stable security definer set search_path = '' as $$
  select other <> (select auth.uid())
     and exists (select 1 from public.follows
                 where follower_id = (select auth.uid()) and following_id = other)
     and exists (select 1 from public.follows
                 where follower_id = other and following_id = (select auth.uid()))
     and not private.is_blocked_with(other);
$$;
revoke all on function private.can_message(uuid) from public, anon;
grant execute on function private.can_message(uuid) to authenticated;

create table if not exists public.conversations (
  id uuid primary key default gen_random_uuid(),
  user_a uuid not null references public.profiles(id) on delete cascade,
  user_b uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  last_message_at timestamptz,
  a_read_at timestamptz,
  b_read_at timestamptz,
  check (user_a < user_b),
  unique (user_a, user_b)
);
create index if not exists conversations_user_b_idx on public.conversations (user_b);

alter table public.conversations enable row level security;
revoke all on public.conversations from anon, authenticated;
grant select on public.conversations to authenticated;

drop policy if exists "Members see own conversations" on public.conversations;
create policy "Members see own conversations" on public.conversations
  for select to authenticated using (
    (select auth.uid()) in (user_a, user_b)
    and not private.is_blocked_with(case when user_a = (select auth.uid()) then user_b else user_a end)
  );

create table if not exists public.messages (
  id uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations(id) on delete cascade,
  sender_id uuid not null default auth.uid() references public.profiles(id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 2000),
  created_at timestamptz not null default now()
);
create index if not exists messages_conversation_created_idx
  on public.messages (conversation_id, created_at desc);
create index if not exists messages_sender_id_idx on public.messages (sender_id);

alter table public.messages enable row level security;
revoke all on public.messages from anon, authenticated;
grant select on public.messages to authenticated;
grant insert (conversation_id, body) on public.messages to authenticated;

-- Visible with the conversation (members only, hidden after a block).
drop policy if exists "Members read messages" on public.messages;
create policy "Members read messages" on public.messages
  for select to authenticated using (
    exists (select 1 from public.conversations c where c.id = conversation_id)
  );

-- Sending needs a live mutual follow.
drop policy if exists "Mutual followers send messages" on public.messages;
create policy "Mutual followers send messages" on public.messages
  for insert to authenticated with check (
    sender_id = (select auth.uid())
    and exists (
      select 1 from public.conversations c
      where c.id = conversation_id
        and (select auth.uid()) in (c.user_a, c.user_b)
        and private.can_message(case when c.user_a = (select auth.uid()) then c.user_b else c.user_a end)
    )
  );

-- New message bumps the conversation and counts as read for the sender.
create or replace function private.touch_conversation()
returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.conversations
     set last_message_at = new.created_at,
         a_read_at = case when user_a = new.sender_id then new.created_at else a_read_at end,
         b_read_at = case when user_b = new.sender_id then new.created_at else b_read_at end
   where id = new.conversation_id;
  return new;
end;
$$;
revoke all on function private.touch_conversation() from public, anon, authenticated;

drop trigger if exists messages_touch_conversation on public.messages;
create trigger messages_touch_conversation
  after insert on public.messages
  for each row execute function private.touch_conversation();

-- Rate limit: same trigger as posts/comments, plus messages (60 per 10 minutes).
create or replace function private.enforce_rate_limit()
returns trigger
language plpgsql security definer set search_path to 'public' as $function$
declare
  n int;
begin
  if coalesce(current_setting('role', true), 'none') not in ('authenticated', 'anon') then
    return new;
  end if;
  new.created_at := now();
  perform pg_advisory_xact_lock(hashtext(tg_table_name || coalesce(auth.uid()::text, '')));
  if tg_table_name = 'posts' then
    select count(*) into n from public.posts
    where author_id = auth.uid() and created_at > now() - interval '10 minutes';
    if n >= 10 then raise exception 'rate_limit' using hint = 'posts'; end if;
  elsif tg_table_name = 'comments' then
    select count(*) into n from public.comments
    where author_id = auth.uid() and created_at > now() - interval '10 minutes';
    if n >= 30 then raise exception 'rate_limit' using hint = 'comments'; end if;
  elsif tg_table_name = 'reports' then
    select count(*) into n from public.reports
    where reporter_id = auth.uid() and created_at > now() - interval '1 day';
    if n >= 20 then raise exception 'rate_limit' using hint = 'reports'; end if;
  elsif tg_table_name = 'groups' then
    select count(*) into n from public.groups
    where creator_id = auth.uid() and created_at > now() - interval '1 day';
    if n >= 5 then raise exception 'rate_limit' using hint = 'groups'; end if;
  elsif tg_table_name = 'messages' then
    select count(*) into n from public.messages
    where sender_id = auth.uid() and created_at > now() - interval '10 minutes';
    if n >= 60 then raise exception 'rate_limit' using hint = 'messages'; end if;
  end if;
  return new;
end;
$function$;

drop trigger if exists messages_rate_limit on public.messages;
create trigger messages_rate_limit
  before insert on public.messages
  for each row execute function private.enforce_rate_limit();

-- Opens (or returns) the conversation with a mutual follower.
create or replace function public.start_conversation(p_other uuid)
returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  cid uuid;
begin
  if me is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if not private.can_message(p_other) then
    raise exception 'not mutual followers' using errcode = '42501';
  end if;
  insert into public.conversations (user_a, user_b)
    values (least(me, p_other), greatest(me, p_other))
    on conflict (user_a, user_b) do nothing
    returning id into cid;
  if cid is null then
    select id into cid from public.conversations
     where user_a = least(me, p_other) and user_b = greatest(me, p_other);
  end if;
  return cid;
end;
$$;
revoke all on function public.start_conversation(uuid) from public, anon;
grant execute on function public.start_conversation(uuid) to authenticated;

create or replace function public.mark_conversation_read(p_conversation uuid)
returns void
language sql security definer set search_path = '' as $$
  update public.conversations
     set a_read_at = case when user_a = auth.uid() then now() else a_read_at end,
         b_read_at = case when user_b = auth.uid() then now() else b_read_at end
   where id = p_conversation and auth.uid() in (user_a, user_b);
$$;
revoke all on function public.mark_conversation_read(uuid) from public, anon;
grant execute on function public.mark_conversation_read(uuid) to authenticated;

-- Inbox: one row per conversation with the other member and the latest message.
create or replace function public.my_conversations()
returns table (
  conversation_id uuid, other_id uuid, last_body text, last_sender_id uuid,
  last_message_at timestamptz, unread boolean, can_send boolean
)
language sql stable security invoker set search_path = '' as $$
  select c.id,
         o.other,
         m.body,
         m.sender_id,
         c.last_message_at,
         c.last_message_at is not null
           and c.last_message_at > coalesce(case when c.user_a = auth.uid() then c.a_read_at else c.b_read_at end, '-infinity'),
         private.can_message(o.other)
  from public.conversations c
  cross join lateral (select case when c.user_a = auth.uid() then c.user_b else c.user_a end as other) o
  left join lateral (
    select body, sender_id from public.messages
     where conversation_id = c.id order by created_at desc limit 1
  ) m on true
  where c.last_message_at is not null
  order by c.last_message_at desc;
$$;
revoke all on function public.my_conversations() from public, anon;
grant execute on function public.my_conversations() to authenticated;

-- Realtime for new messages (RLS applies to subscribers).
do $$ begin
  if not exists (select 1 from pg_publication_tables
                 where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages') then
    alter publication supabase_realtime add table public.messages;
  end if;
end $$;

commit;
